/* Ensure kerning is applied for precise letter spacing */
h1, h2, .display-text {
  font-kerning: normal; /* Apply the font's built-in kerning information */
  letter-spacing: -0.02em; /* Optional: fine-tune general letter spacing */
  text-rendering: optimizeLegibility; /* Hint for better text rendering, often enables kerning implicitly */
}

/* Disable kerning for specific cases, e.g., monospaced fonts or performance */
.code-block {
  font-kerning: none;
}
